WORKLOADS = [
    ("payments", 10, 0),
    ("orders", 45, 10),
    ("analytics", 180, 60),
    ("archive", 1440, 720),
]

def classify(rto_min, rpo_min):
    if rto_min <= 15 and rpo_min <= 5:
        return "multi_site_active_active"
    if rto_min <= 60 and rpo_min <= 15:
        return "warm_standby"
    if rto_min <= 240 and rpo_min <= 60:
        return "pilot_light"
    return "backup_restore"

total = 0
for name, rto, rpo in WORKLOADS:
    tier = classify(rto, rpo)
    print(f"{name} (RTO={rto}m RPO={rpo}m): {tier}")
    total += 1
print(f"Tiers assigned: {total}")
